graders.command:
python3 "$EVAL_COSMOS_ROOT/workflow/verify-artifacts.py" . && python3 -c "import glob,re,subprocess,sys;p=glob.glob('.scratch/*/FEATURE.md')[0];n=open(p,encoding='utf-8').read();o=subprocess.run(['git','show','eval-base:'+p],capture_output=True,text=True,check=True).stdout;sec=lambda t,h:''.join(re.findall(r'^## '+h+r'[^
]*
(.*?)(?=^## |\Z)',t,re.S|re.M));dec=lambda t:dict(re.findall(r'^### (D\d+)[^
]*
(.*?)(?=^##|\Z)',sec(t,'决策'),re.S|re.M));lo=sec(o,'变更记录').splitlines();ln=sec(n,'变更记录').splitlines();add=[l for l in ln if l not in lo and re.match(r'- \d{4}-\d{2}-\d{2} ',l)];ch=[k for k,v in dec(o).items() if dec(n).get(k)!=v];print(ch,add);sys.exit(not ch or any(l not in ln for l in lo) or not all(any(re.search(r' '+k+r' ',l) for l in add) for k in ch))"
